// src/components/MovieCard.js

import React from 'react';
// SCSS에서 참조하는 기본 이미지를 import 합니다.
// 이 이미지는 실제 프로젝트의 'src/assets/images/' 폴더에 있어야 합니다.
import defaultPoster from '../assets/images/post_default.jpg';

/**
 * SCSS 기반의 새로운 영화 카드 컴포넌트
 * @param {object} movie - 영화 데이터 객체
 * @param {string} size - 카드 크기 ('m', 'L', 's').
 */
function MovieCard({ movie, size = 'm' }) {
  // 포스터 이미지가 없을 경우 기본 이미지 사용
  const posterStyle = {
    backgroundImage: `url(${movie.posterPath || defaultPoster})`
  };

  return (
    <div className={`card-${size}`} style={posterStyle}>
      {/* SCSS 규칙(.card-m:hover .show-contents)에 따라
        이 div는 마우스를 올렸을 때만 보이게 됩니다.
      */}
      <div className="show-contents">
        <div className="wrapper-movie-title">
          <h3 id="movie-title">{movie.title}</h3>
          <p id="movie-title-eng">{movie.englishTitle}</p>
        </div>

        {movie.details && (
          <div className="wrapper-sub-text">
            {Object.entries(movie.details).map(([key, value]) => (
              // SCSS 구조에 맞춰 key와 value를 렌더링
              <div className="sub-title" key={key}>
                {key}
                <div className="sub-text">{value}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default MovieCard;
